#include <stdbool.h>
#include <string.h>

extern bool is_left(char ch);
extern bool is_right(char ch);
extern char right_partner(char ch);

bool is_balanced(const char *str) {
    bool result = false;
    size_t n = strlen(str);
    if (n < 2) return false;
    char *stack = malloc(n);
    int top = 0;
    for (size_t i = 0; i < n; i++) {
        char ch = str[i];
        if (!is_right(ch) && !is_left(ch)) {
            continue;
        }
        if (is_left(ch)) {
            stack[top++] = ch;
        } else {
            if (top > 0 && stack[--top] == right_partner(ch)) {
                result = true;
            } else {
                free(stack);
                return false;
            }
        }
    }
    if (top != 0) {
        result = false;
    }
    free(stack);
    return result;
}

