int solution(int X, int *A, int n) {
    int cap = 1;
    for (int i = 0; i < n; i++) if (A[i] + 1 > cap) cap = A[i] + 1;
    if (X + 1 > cap) cap = X + 1;
    char *seen = calloc(cap, 1);
    int size = 0;
    for (int i = 0; i < n; i++) {
        if (A[i] >= 0 && !seen[A[i]]) {
            seen[A[i]] = 1;
            size++;
        }
        if (seen[X] && size == X) {
            free(seen);
            return i;
        }
    }
    free(seen);
    return -1;
}

