    char *seen = calloc(cap, 1);
    int sum1 = 0, sum2 = 0;
    for (int i = 0; i <= X; i++) {
        sum1 += i;
    }
    for (int i = 0; i < n; i++) {
        if (seen[A[i]]) continue;
        seen[A[i]] = 1;
