public static IEnumerable < IEnumerable < T > > GetPermutations < T > (IEnumerable < IEnumerable < T > > lists) {
    if (! lists.Any ()) {
        yield break;
    }
    List < IEnumerator < T > > iterators = new List < IEnumerator < T > > ();
    foreach (var list in lists) {
        var it = list.GetEnumerator ();
        if (it.MoveNext ()) {
            iterators.Add (it);
        }
    }
    int pos;
    do {
        yield return iterators.Select (it => it.Current).ToList ();
        pos = 0;
        while (pos < iterators.Count) {
            var cur = iterators [pos];
            if (cur.MoveNext ()) {
                break;
            }
            cur.Reset ();
            cur.MoveNext ();
            pos ++;
        }
    } while (pos < iterators.Count);
}

